// Authorization { long amountMinor; int merchantId; boolean approved; String authCode; }
// default:          12 + 8 + 4 + 1 + 4 = 29 -> 32 bytes
// no compressed oops: 12 + 8 + 4 + 1 + 8 = 33 -> 40 bytes
// compact headers:   8 + 8 + 4 + 1 + 4 = 25 -> 32 bytes (padding eats the saving)
static long alignUp(long size, int alignment) {
    return (size + alignment - 1) / alignment * alignment;
}

